-- Release hardening: payment-link state gating, gateway reconciliation, idempotency,\n-- invoice template validation, and consistent GST profile normalization.\n\n-- A customer-facing payment link is valid only for a billable invoice.\nCREATE OR REPLACE FUNCTION public.assert_invoice_payment_linkable(p_invoice_id uuid)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, mm_private\nAS $$\nDECLARE v_status text; v_business_id uuid;\nBEGIN\n  SELECT status::text, business_id INTO v_status, v_business_id\n  FROM public.invoices WHERE id=p_invoice_id;\n  IF v_business_id IS NULL THEN RAISE EXCEPTION 'Invoice not found'; END IF;\n  IF v_status NOT IN ('sent','posted','partially_paid','overdue') THEN\n    RAISE EXCEPTION 'Payment links require a posted or billable invoice';\n  END IF;\nEND;\n$$;\nREVOKE ALL ON FUNCTION public.assert_invoice_payment_linkable(uuid) FROM PUBLIC, anon, authenticated;\n\n-- Canonical gateway transaction idempotency. NULLs remain allowed for non-gateway payments.\nCREATE UNIQUE INDEX IF NOT EXISTS payments_business_gateway_transaction_uidx\n  ON public.payments(business_id, gateway_transaction_id)\n  WHERE gateway_transaction_id IS NOT NULL;\n\n-- Gateway reconciliation is intentionally service-role-only. The webhook supplies only\n-- provider identity + local payment-link identity; all business/customer/invoice/account\n-- relationships are resolved from trusted database rows.\nCREATE OR REPLACE FUNCTION public.record_gateway_payment(\n  p_provider text,\n  p_provider_link_id text,\n  p_provider_transaction_id text,\n  p_event_id text,\n  p_amount numeric,\n  p_payment_date date DEFAULT current_date,\n  p_notes text DEFAULT NULL\n)\nRETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, mm_private\nAS $$\nDECLARE\n  v_link public.payment_links%rowtype;\n  v_inv public.invoices%rowtype;\n  v_payment uuid; v_receipt uuid; v_entry uuid; v_ar uuid; v_account uuid;\n  v_allocated numeric; v_receipt_number text;\nBEGIN\n  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Service role required'; END IF;\n  IF lower(coalesce(p_provider,'')) <> 'razorpay' THEN RAISE EXCEPTION 'Unsupported payment provider'; END IF;\n  IF nullif(trim(p_provider_link_id),'') IS NULL THEN RAISE EXCEPTION 'Provider link id is required'; END IF;\n  IF nullif(trim(p_provider_transaction_id),'') IS NULL THEN RAISE EXCEPTION 'Provider transaction id is required'; END IF;\n  IF p_amount <= 0 THEN RAISE EXCEPTION 'Payment amount must be greater than zero'; END IF;\n\n  SELECT * INTO v_link FROM public.payment_links\n  WHERE provider='razorpay' AND provider_link_id=p_provider_link_id FOR UPDATE;\n  IF v_link.id IS NULL THEN RAISE EXCEPTION 'Payment link not found'; END IF;\n\n  SELECT * INTO v_inv FROM public.invoices\n  WHERE id=v_link.invoice_id AND business_id=v_link.business_id FOR UPDATE;\n  IF v_inv.id IS NULL THEN RAISE EXCEPTION 'Invoice not found'; END IF;\n  IF v_inv.status='void' THEN RAISE EXCEPTION 'Cannot record payment for void invoice'; END IF;\n  IF p_amount > greatest(v_inv.balance_due,0) THEN RAISE EXCEPTION 'Payment exceeds invoice balance'; END IF;\n\n  SELECT id INTO v_payment FROM public.payments\n  WHERE business_id=v_link.business_id AND gateway_transaction_id=p_provider_transaction_id\n  LIMIT 1;\n  IF v_payment IS NOT NULL THEN\n    SELECT id INTO v_receipt FROM public.receipts WHERE payment_id=v_payment LIMIT 1;\n    RETURN coalesce(v_receipt,v_payment);\n  END IF;\n\n  -- A gateway payment must settle an already-posted invoice. Never silently post it here.\n  IF v_inv.journal_entry_id IS NULL THEN RAISE EXCEPTION 'Invoice must be posted before gateway payment'; END IF;\n\n  SELECT id INTO v_account FROM public.accounts\n  WHERE business_id=v_link.business_id AND code='1010' AND is_active LIMIT 1;\n  IF v_account IS NULL THEN RAISE EXCEPTION 'Gateway payment account is missing'; END IF;\n  SELECT id INTO v_ar FROM public.accounts\n  WHERE business_id=v_link.business_id AND code='1100' AND is_active LIMIT 1;\n  IF v_ar IS NULL THEN RAISE EXCEPTION 'Accounts receivable account is missing'; END IF;\n\n  INSERT INTO public.payments(\n    business_id,direction,customer_id,invoice_id,account_id,amount,currency_code,\n    payment_date,method,reference,gateway_transaction_id,notes,created_by\n  ) VALUES (\n    v_link.business_id,'inbound',v_inv.customer_id,v_inv.id,v_account,p_amount,\n    v_inv.currency_code,p_payment_date,'payment_gateway'::public.payment_method,\n    coalesce(p_provider_transaction_id,p_event_id),p_provider_transaction_id,\n    coalesce(p_notes,'Gateway payment: '||p_provider),NULL\n  ) RETURNING id INTO v_payment;\n\n  INSERT INTO public.payment_allocations(business_id,payment_id,invoice_id,amount)\n  VALUES(v_link.business_id,v_payment,v_inv.id,p_amount);\n\n  PERFORM pg_advisory_xact_lock(hashtext('journal-entry-number:'||v_link.business_id::text));\n  INSERT INTO public.journal_entries(\n    business_id,entry_number,entry_date,description,source_type,source_id,status,\n    posted_at,posted_by,created_by,currency_code,total_debit,total_credit,is_system_generated\n  ) VALUES(\n    v_link.business_id,\n    (SELECT coalesce(max(entry_number),0)+1 FROM public.journal_entries WHERE business_id=v_link.business_id),\n    p_payment_date,'Gateway payment for invoice '||v_inv.invoice_number,'payment',v_payment,\n    'posted',now(),NULL,NULL,v_inv.currency_code,p_amount,p_amount,true\n  ) RETURNING id INTO v_entry;\n\n  INSERT INTO public.journal_lines(journal_entry_id,account_id,description,debit,credit,currency_code,entity_type,entity_id)\n  VALUES(v_entry,v_account,'Gateway customer payment',p_amount,0,v_inv.currency_code,'customer',v_inv.customer_id),\n        (v_entry,v_ar,'Receivable settlement',0,p_amount,v_inv.currency_code,'customer',v_inv.customer_id);\n  PERFORM public.validate_journal_entry_balance(v_entry);\n  UPDATE public.payments SET journal_entry_id=v_entry WHERE id=v_payment;\n\n  SELECT coalesce(sum(pa.amount),0) INTO v_allocated\n  FROM public.payment_allocations pa WHERE pa.invoice_id=v_inv.id;\n  UPDATE public.invoices SET\n    amount_paid=v_allocated,\n    balance_due=greatest(total-v_allocated,0),\n    status=CASE\n      WHEN v_allocated>=total THEN 'paid'::invoice_status\n      WHEN v_allocated>0 AND due_date<current_date THEN 'overdue'::invoice_status\n      WHEN v_allocated>0 THEN 'partially_paid'::invoice_status\n      WHEN due_date<current_date THEN 'overdue'::invoice_status\n      ELSE 'sent'::invoice_status END,\n    updated_at=now()\n  WHERE id=v_inv.id;\n\n  v_receipt_number:=public.next_document_number(v_link.business_id,'receipt');\n  INSERT INTO public.receipts(\n    business_id,customer_id,payment_id,receipt_number,receipt_date,amount,currency_code,\n    payment_method,reference_number,notes,created_by\n  ) VALUES(\n    v_link.business_id,v_inv.customer_id,v_payment,v_receipt_number,p_payment_date,p_amount,\n    v_inv.currency_code,'payment_gateway',p_provider_transaction_id,p_notes,NULL\n  ) RETURNING id INTO v_receipt;\n  RETURN v_receipt;\nEND;\n$$;\n\nREVOKE ALL ON FUNCTION public.record_gateway_payment(text,text,text,text,numeric,date,text) FROM PUBLIC, anon, authenticated;\nGRANT EXECUTE ON FUNCTION public.record_gateway_payment(text,text,text,text,numeric,date,text) TO service_role;\n\n-- Harden the draft editor without changing its public signature.\nCREATE OR REPLACE FUNCTION public.update_invoice_draft(\n  p_invoice_id uuid,p_customer_id uuid,p_invoice_date date,p_due_date date,p_items jsonb,\n  p_invoice_discount_type text DEFAULT NULL,p_invoice_discount_value numeric DEFAULT 0,\n  p_notes text DEFAULT NULL,p_terms text DEFAULT NULL,p_template_id uuid DEFAULT NULL\n) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='public','mm_private' AS $$\nDECLARE\n  inv public.invoices%rowtype; v_tax_enabled boolean; v_item jsonb; v_product uuid; v_qty numeric; v_price numeric;\n  v_desc text; v_disc_type text; v_disc_value numeric; v_tax uuid; v_base numeric; v_line_discount numeric;\n  v_tax_rate numeric; v_tax_amount numeric; v_line_total numeric; v_discount_type text;\nBEGIN\n  SELECT * INTO inv FROM public.invoices WHERE id=p_invoice_id FOR UPDATE;\n  IF inv.id IS NULL THEN RAISE EXCEPTION 'Invoice not found'; END IF;\n  IF NOT (mm_private.has_business_permission(inv.business_id,'sales.edit') OR mm_private.has_business_permission(inv.business_id,'sales.create')) THEN RAISE EXCEPTION 'Access denied'; END IF;\n  IF inv.status <> 'draft' OR inv.journal_entry_id IS NOT NULL THEN RAISE EXCEPTION 'Only draft invoices can be edited'; END IF;\n  IF NOT EXISTS(SELECT 1 FROM public.customers WHERE id=p_customer_id AND business_id=inv.business_id AND is_active) THEN RAISE EXCEPTION 'Customer not found or inactive'; END IF;\n  IF jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items)=0 THEN RAISE EXCEPTION 'At least one invoice item is required'; END IF;\n  IF p_template_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.document_templates WHERE id=p_template_id AND document_type='invoice' AND is_active) THEN RAISE EXCEPTION 'Invalid or inactive invoice template'; END IF;\n\n  SELECT coalesce(upper(tp.tax_regime)='GST' AND coalesce(upper(tp.gst_registration_type),'NONE') <> 'COMPOSITION',false)\n    INTO v_tax_enabled FROM public.business_tax_profiles tp WHERE tp.business_id=inv.business_id;\n  v_tax_enabled:=coalesce(v_tax_enabled,false);\n  IF p_invoice_discount_type='amount' THEN v_discount_type='fixed'; ELSE v_discount_type=p_invoice_discount_type; END IF;\n\n  UPDATE public.invoices SET customer_id=p_customer_id,invoice_date=coalesce(p_invoice_date,invoice_date),due_date=coalesce(p_due_date,due_date),\n    notes=p_notes,terms=p_terms,discount_type=v_discount_type,discount_value=coalesce(p_invoice_discount_value,0),template_id=p_template_id,updated_at=now()\n  WHERE id=p_invoice_id;\n  DELETE FROM public.invoice_items WHERE invoice_id=p_invoice_id;\n\n  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP\n    v_product:=nullif(v_item->>'product_service_id','')::uuid; v_qty:=coalesce((v_item->>'quantity')::numeric,0);\n    v_price:=coalesce((v_item->>'unit_price')::numeric,0); v_desc:=coalesce(nullif(v_item->>'description',''),(select name from public.products_services where id=v_product));\n    v_disc_type:=nullif(v_item->>'discount_type',''); IF v_disc_type='amount' THEN v_disc_type='fixed'; END IF;\n    v_disc_value:=coalesce((v_item->>'discount_value')::numeric,0); v_tax:=nullif(v_item->>'tax_rate_id','')::uuid;\n    IF v_qty<=0 OR v_price<0 OR v_desc IS NULL THEN RAISE EXCEPTION 'Invalid invoice item'; END IF;\n    IF v_product IS NOT NULL AND NOT EXISTS(select 1 from public.products_services where id=v_product and business_id=inv.business_id and is_active and sell_enabled) THEN RAISE EXCEPTION 'Product/service not found'; END IF;\n    v_base:=round(v_qty*v_price,2); v_line_discount:=public.calculate_invoice_discount(v_base,v_disc_type,v_disc_value);\n    v_tax_rate:=case when v_tax_enabled and v_tax is not null then coalesce((select rate from public.tax_rates where id=v_tax and business_id=inv.business_id and is_active),0) else 0 end;\n    v_tax_amount:=round((v_base-v_line_discount)*v_tax_rate/100,2); v_line_total:=round(v_base-v_line_discount+v_tax_amount,2);\n    INSERT INTO public.invoice_items(invoice_id,product_service_id,description,quantity,unit_price,discount,discount_type,discount_value,unit_price_before_discount,tax_rate_id,tax_amount,line_total,sort_order)\n    VALUES(p_invoice_id,v_product,v_desc,v_qty,v_price,v_line_discount,v_disc_type,v_disc_value,v_price,v_tax,v_tax_amount,v_line_total,(select coalesce(max(sort_order),-1)+1 from public.invoice_items where invoice_id=p_invoice_id));\n  END LOOP;\n  PERFORM public.recalculate_invoice_totals(p_invoice_id); RETURN p_invoice_id;\nEND;\n$$;\n